/* Linear index of derivative key (a,b,c), matching the table order:
   degree n = a+b+c ascending, then a ascending, then b ascending (c = n-a-b). */
static inline int der_key(int a, int b, int c) {
    int n = a + b + c;
    int base = n * (n + 1) * (n + 2) / 6;
    return base + a * (n + 1) - a * (a - 1) / 2 + b;
}

